      }
      report.finishedAt = this.clock()
      this.setMeta("sleep_cursor", String(report.toCursor))
      this.db.query("INSERT INTO sleep_reports(id,body) VALUES(?,?)").run(report.id, JSON.stringify(report))
      this.changed("sleep", report.id)
      return report
    })()
  }

