  recoverInterrupted() {
    this.db.transaction(() => {
      for (const task of this.tasks().filter(task => task.status === "running")) {
        this.updateTask(task.id, { status: "waiting", error: "上次运行中断，需要先核实后端结果；不会自动重发操作" })
